<script setup>
import {Head,Link,router,usePage} from '@inertiajs/vue3';import {art,modes,date} from '../art';
defineProps({catalog:Object,stats:Object,assignments:Array,daily:Object,deck:Object});const page=usePage();
</script><template><Head title="The Counter"/><div class="counter-welcome"><p class="eyebrow">Welcome, {{page.props.community.profile.display_name}}</p><h1>What will you study today?</h1></div>
<div class="focused-home">
<section class="panel home-study-card"><img :src="art.temaki" alt="" class="home-character"><div><h2>Fresh Catch 10</h2><p v-if="daily.completed_today">Today's catch complete ✓</p><p v-else-if="daily.attempt">{{daily.answered}}/10 answered</p><p v-else>Ten questions. One daily habit.</p><Link :href="daily.attempt?'/attempts/'+daily.attempt:'/practice?mode=fresh'" class="button primary">{{daily.attempt?'Resume catch':daily.completed_today?'Another catch':'Start catch'}}</Link></div><p v-if="!daily.available" class="muted">Fewer than 10 eligible questions. Choose more subjects.</p><details v-if="daily.remind" class="quiet-reminder"><summary>Reminder</summary><button class="plain" @click="router.post('/reminders/dismiss',{action:'snooze'},{preserveScroll:true})">In 1 hour</button><button class="plain" @click="router.post('/reminders/dismiss',{action:'skip'},{preserveScroll:true})">Dismiss today</button></details></section>
<section class="panel home-study-card"><img :src="art.memo" alt="" class="home-character"><div><h2>Memory Maki</h2><p v-if="deck">{{deck.confident}}/{{deck.total}} cards rated 5</p><p v-else>Answer. Rate. Remember.</p><Link :href="deck?'/flashcards/decks/'+deck.id:'/flashcards?new=1'" class="button primary">{{deck?'Open deck':'New deck'}}</Link> <Link v-if="deck" class="secondary-link" href="/flashcards?decks=1">Saved decks</Link></div></section>
</div><section class="home-progress" aria-label="Study progress"><div><strong>{{stats.completed}}</strong><span>Questions completed</span></div><div><strong>{{stats.first_total?Math.round(stats.first_correct/stats.first_total*100)+'%':'—'}}</strong><span>First-answer accuracy</span></div><Link class="button" href="/progress">View progress</Link></section>
<section v-if="assignments.length" class="panel"><h2>Assigned exams</h2><div v-for="a in assignments" :key="a.id" class="row spaced"><div><strong>{{a.exam.title}}</strong><p>{{date(a.opens_at)}} to {{date(a.closes_at)}} · {{a.minutes}} min</p></div><button @click="router.post('/assignments/'+a.id+'/start')">Open exam</button></div></section>
<section v-if="stats.attempts.some(a=>a.status==='active'&&a.mode!=='fresh')" class="panel"><h2>Unfinished rounds</h2><div v-for="a in stats.attempts.filter(a=>a.status==='active'&&a.mode!=='fresh')" :key="a.id" class="row"><span>{{modes[a.mode]}} · {{a.items_count}} questions</span><Link :href="'/attempts/'+a.id" class="button">Resume</Link></div></section>
</template>
